  needs=[("Event portfolio", "Photos and short stories of weddings you planned, with size and style."),
         ("Planning packages", "Day-of coordination, full planning and destination options, with starting budgets."),
         ("A transparent process", "From first call to wedding day, show each step and who handles it."),
         ("Vendor network", "Decorators, caterers, photographers and artists you work with."),
         ("Consultation booking", "A form that captures date, guest count and city on WhatsApp."),
         ("Testimonials with permission", "Short notes from couples describing the experience.")],
  mistakes=[("Showing only decoration photos", "Couples also want to know how you manage timelines and budgets. Explain the process."),
            ("No budget indication", "Without a range, serious and casual enquiries look the same. Give starting packages."),
            ("Slow replies", "Wedding dates book fast. Use WhatsApp so enquiries reach you instantly.")],
  faq=[("How much does a wedding planner website cost in Kerala?", "A wedding planner website with a portfolio, packages and a consultation form typically costs ₹12,000 to ₹25,000 with Qrenzy, and a one-page version starts at ₹5,000."),
       ("What should a wedding planner's website include?", "A portfolio of real events, packages with starting budgets, the planning process, vendor partners, testimonials and a consultation form."),
       ("Can couples book a planning call from the site?", "Yes. The form opens WhatsApp with the wedding date, guest count and city filled in so you can propose a time."),
       ("Do I need separate pages for destination weddings?", "If you offer them, yes. A dedicated page lets you explain locations, logistics and pricing, and matches specific searches.")],
