I(demo="accounting", url="chartered-accountants", name="Chartered Accountants & Tax Consultants", short="Chartered Accountant", singular="CA firm",
  kf="service pages, fee guidance, a documents checklist and consultation requests",
  intro="Business owners look for an accountant they can trust with money and compliance. A CA firm website should explain services in plain language, set expectations on documents and fees and let a prospect request a consultation.",
  queries=["chartered accountant in Thrissur", "GST registration Kochi", "income tax filing near me", "company registration Kozhikode", "bookkeeping services Kerala"],
  needs=[("A page per service", "GST, income tax, company registration, audit and bookkeeping each explained simply."),
         ("Documents checklist", "What a client must bring for each service saves time on both sides."),
         ("Fee guidance", "Starting fees for common services help clients self-qualify."),
         ("Consultation request", "A form that captures the service needed and business type on WhatsApp."),
         ("About the firm", "Qualifications, experience and the people clients will work with."),
         ("Professional guidelines", "Present information within the guidelines your professional body sets for member websites.")],
  mistakes=[("Heavy compliance jargon", "Write for business owners, not other accountants."),
            ("No fee signal", "Even a range reduces back-and-forth. Explain what changes the fee."),
            ("Outdated deadlines", "Wrong due dates harm credibility. Keep content current or avoid dates.")],
  faq=[("How much does a CA firm website cost in Kerala?", "A CA firm website with service pages, a documents checklist and a consultation form typically costs ₹12,000 with Qrenzy, and a one-page version starts at ₹5,000. First-year domain and hosting are included."),
       ("What should an accountant's website include?", "Service pages, fee guidance, documents checklists, about the firm, contact and FAQs. Keep the tone professional and within your institute's guidelines."),
       ("Can accountants publish tax guidance?", "Helpful explainers on common topics attract searches, but they must be accurate and dated. Anything time-sensitive should be reviewed regularly."),
       ("Are there rules on how CAs advertise?", "Yes. Professional bodies set rules on how members may present themselves online. Check the current guidelines before publishing and we will follow them in the content you approve.")],
  related=["legal", "finance-insurance", "corporate-b2b"])

